shell_commands:
mkdir -p /tmp/rs && cat > /tmp/rs/fix.mjs <<'EOF'
import {readFileSync, writeFileSync} from 'node:fs';
import {execSync} from 'node:child_process';
const testFile = 'src/orchestration/chatOrchestrator.test.ts';
const lines = readFileSync(testFile, 'utf8').split('\n');
const specs = execSync("grep -rl 'chatOrchestrator.test.ts#L' specs docs .specify README.md 2>/dev/null || true").toString().trim().split('\n').filter(Boolean);
const re = /\[validated by: ([^\]]+)\]\(([^)]*chatOrchestrator\.test\.ts)#L(\d+)\)/g;
for (const s of specs) {
  const src = readFileSync(s, 'utf8');
  const out = src.replace(re, (m, name, path, ln) => {
    const hits = lines.flatMap((l, i) => (l.includes(`'${name}'`) || l.includes(`"${name}"`) || l.includes('`' + name + '`')) && /\b(it|test)\(/.test(l) ? [i + 1] : []);
    if (hits.length !== 1) { console.log('UNMAPPED', s, name, ln, hits); return m; }
    if (String(hits[0]) !== ln) console.log('moved', s, name, ln, '->', hits[0]);
    return `[validated by: ${name}](${path}#L${hits[0]})`;
  });
  if (out !== src) writeFileSync(s, out);
}
EOF
node /tmp/rs/fix.mjs
